def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    for r, c in sixes:
        out[r][c] = 0

    rmin = min(r for r, c in fours)
    rmax = max(r for r, c in fours)
    cmin = min(c for r, c in fours)
    cmax = max(c for r, c in fours)

    srmin = min(r for r, c in sixes)
    srmax = max(r for r, c in sixes)
    scmin = min(c for r, c in sixes)
    scmax = max(c for r, c in sixes)
    sset = set(sixes)

    # A T-shaped marker specifies a left/right reflection;
    # a cross-shaped marker specifies a downward reflection.
    horizontal_t = any(
        all((r, c) in sset for c in range(scmin, scmax + 1))
        and (srmin == r or srmax == r)
        for r in range(srmin, srmax + 1)
    )

    if horizontal_t:
        marker_c = sum(c for r, c in sixes) / len(sixes)
        shape_c = sum(c for r, c in fours) / len(fours)
        if marker_c < shape_c:
            for r, c in fours:
                cc = 2 * cmin - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:
            for r, c in fours:
                cc = 2 * cmax + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        for r, c in fours:
            rr = 2 * rmax + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4

    return out
